Plan: read the A2:E8 data, keep only rows whose date equals the maximum date for each brand, then sum quantities by brand/batch/origin for those last-date rows. Write the resulting date, brand, batch, origin, and quantity into H2:L4 as plain values.

```python
import shutil
import openpyxl
from datetime import datetime, date

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb["ورقة1"]
vws = vals["ورقة1"]

def to_date(value):
    if isinstance(value, datetime):
        return value.date()
    if isinstance(value, date):
        return value
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        try:
            return datetime.fromordinal(int(value)).date()
        except Exception:
            return None
    if isinstance(value, str):
        s = value.strip()
        for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%d", "%d/%m/%Y", "%m/%d/%Y"):
            try:
                return datetime.strptime(s, fmt).date()
            except Exception:
                pass
    return None

def to_number(value):
    if isinstance(value, bool):
        return 0
    if isinstance(value, (int, float)):
        return value
    if isinstance(value, str):
        try:
            return float(value.strip())
        except Exception:
            return 0
    return 0

def clean_text(value):
    if value is None:
        return ""
    return str(value).strip()

rows = []
for r in range(2, vws.max_row + 1):
    d = to_date(vws.cell(row=r, column=1).value)
    if d is None:
        continue
    brand = clean_text(vws.cell(row=r, column=2).value)
    batch = clean_text(vws.cell(row=r, column=3).value)
    origin = clean_text(vws.cell(row=r, column=4).value)
    qty = to_number(vws.cell(row=r, column=5).value)
    rows.append((d, brand, batch, origin, qty))

max_date_by_brand = {}
for d, brand, _, _, _ in rows:
    if brand not in max_date_by_brand or d > max_date_by_brand[brand]:
        max_date_by_brand[brand] = d

aggregated = {}
for d, brand, batch, origin, qty in rows:
    if max_date_by_brand.get(brand) == d:
        key = (brand, batch, origin)
        if key not in aggregated:
            aggregated[key] = {"date": d, "qty": 0}
        aggregated[key]["date"] = d
        aggregated[key]["qty"] += qty

results = []
for (brand, batch, origin), info in aggregated.items():
    results.append((info["date"], brand, batch, origin, info["qty"]))

results.sort(key=lambda x: (x[0], x[1], x[2], x[3]))

for r in range(2, 5):
    for c in range(8, 13):
        ws.cell(row=r, column=c).value = None

for i, (d, brand, batch, origin, qty) in enumerate(results[:3]):
    r = 2 + i
    ws.cell(row=r, column=8).value = d
    ws.cell(row=r, column=9).value = brand
    ws.cell(row=r, column=10).value = batch
    ws.cell(row=r, column=11).value = origin
    ws.cell(row=r, column=12).value = qty

wb.save(OUT)

print("rows:", len(rows))
print("max_date_by_brand:", max_date_by_brand)
print("results:", results)
